@startuml

class Department {}

class Room {}

class Bed {}

class Category {
  +price: double
}

class RestHome extends Category {}

class RestAndNursingHome extends Category {}

class ServiceFlat extends Category {}

class Inhabitant {
  +name: string
  +registrationDate: date
}

class Stay {
  +startDate: date
  +endDate: date
  +isSuspended: boolean
  +isInvalidated: boolean
}

class Registration {
  +identificationData: string
  +assessmentResults: string
}

class WaitingListEntry {
  +position: int
}

class Proposal {
  +proposalDate: date
  +isAccepted: boolean
  +isRefused: boolean
  +isInvalidated: boolean
}

class Invoice {
  +date: date
  +outstandingAmount: double
  +status: string
}

class Payment {
  +amount: double
  +date: date
}

class CreditNote {
  +amount: double
  +date: date
}

Department "1" *-- "*" Room
Room "1" *-- "*" Bed
Bed "*" -- "1" Category
Inhabitant "1" -- "*" Stay
Stay "*" -- "1" Category
Inhabitant "1" -- "0..1" Registration
Inhabitant "1" -- "*" WaitingListEntry
WaitingListEntry "*" -- "1" Category
Inhabitant "1" -- "*" Proposal
Proposal "*" -- "1" Category
Inhabitant "1" -- "*" Invoice
Invoice "1" *-- "*" Payment
Invoice "1" -- "0..1" CreditNote
Stay "1" -- "*" Invoice

@enduml

